var n=`0480-shish-taouk`;var r=`world-0480`;var t=`LB`;var a=`western-asia`;var o=4;var s=207;var g={en:`Shish Taouk`,ua:`Шиш-таук`};var l={en:`A traditional dish from Lebanon, centered on chicken breast, plain yogurt, lemon juice, garlic. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: куряча грудка, натуральний йогурт, лимонний сік, часник. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 180 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 180 хвилин.`,t:[`marinating`],m:180,i:[[`chicken-breast`,680,`g`],[`plain-yogurt`,190,`g`],[`lemon-juice`,55,`ml`],[`garlic`,5,`clove`],[`sweet-paprika`,5,`g`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:10,i:[]},{en:`Grill over medium-high heat for about 17 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 17 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:17,i:[[`extra-virgin-olive-oil`,40,`ml`]]}];var c={slug:n,id:r,country:`LB`,region:a,servings:4,minutes:207,title:g,text:l,steps:u};export{t as country,c as default,r as id,s as minutes,a as region,o as servings,n as slug,u as steps,l as text,g as title};